// 1. 指定 Webhook 節點名稱
const webhookNodeName = 'LINE Webhook';

let replyToken = "";
try {
  const webhookData = $(webhookNodeName).first()?.json;
  replyToken = webhookData?.body?.events?.[0]?.replyToken || "";
} catch (e) {
  replyToken = "";
}

// 2. 取得員工資訊
let rawCode = "";
try {
  rawCode = $('比對USERID').first()?.json?.['編號'] || "";
} catch (e) {
  rawCode = "";
}

const numMatch = rawCode.match(/\d+/);
const staffNum = numMatch ? numMatch[0] : '';
const targetStaffName = `${staffNum}號師傅`;

// 3. 設定 7 天日期過濾區間 (從今日起算 7 天)
const today = new Date();
today.setHours(0, 0, 0, 0);

const next7Days = new Date(today);
next7Days.setDate(today.getDate() + 7);

// 4. 取得預約並過濾 (指定師傅 + 未來 7 天內)
const allBookings = $input.all();
const matchedBookings = allBookings
  .map(item => item.json)
  .filter(b => {
    const isStaff = (b['指定師傅'] === targetStaffName || b['指定師傅'] === rawCode);
    if (!isStaff || !b['預約日期']) return false;

    const bookingDate = new Date(b['預約日期']);
    bookingDate.setHours(0, 0, 0, 0);

    return bookingDate >= today && bookingDate < next7Days;
  })
  .sort((a, b) => new Date(`${a['預約日期']} ${a['開始時間']}`) - new Date(`${b['預約日期']} ${b['開始時間']}`));

// 5. 製作 Flex Message 泡泡 Body 內容
const contents = [];

if (matchedBookings.length === 0) {
  contents.push({
    type: "box",
    layout: "vertical",
    margin: "md",
    contents: [
      {
        type: "text",
        text: "未來 7 天內尚無任何預約。",
        size: "md",
        color: "#888888",
        align: "center"
      }
    ]
  });
} else {
  matchedBookings.forEach((b, index) => {
    // 僅讀取姓名，取消電話
    const displayName = b['姓名'] || '未填寫';

    contents.push({
      type: "box",
      layout: "vertical",
      margin: index === 0 ? "none" : "md",
      spacing: "xs",
      contents: [
        {
          type: "box",
          layout: "baseline",
          contents: [
            {
              type: "text",
              text: `📅 ${b['預約日期']}`,
              weight: "bold",
              size: "md",
              color: "#1DB446"
            }
          ]
        },
        {
          type: "box",
          layout: "baseline",
          margin: "xs",
          contents: [
            {
              type: "text",
              text: `⏰ ${b['開始時間']} ~ ${b['結束時間']}`,
              size: "md",
              color: "#333333",
              weight: "bold"
            }
          ]
        },
        {
          type: "box",
          layout: "baseline",
          margin: "xs",
          contents: [
            {
              type: "text",
              text: `💆 ${b['服務項目'] || '未指定'} | 👤 ${displayName}`,
              size: "md",
              color: "#555555",
              weight: "bold"
            }
          ]
        }
      ]
    });

    if (index < matchedBookings.length - 1) {
      contents.push({
        type: "separator",
        margin: "md"
      });
    }
  });
}

// 6. 輸出標準 Flex Bubble 結構 (加入 size: KILO 縮小寬度)
const flexMessage = {
  type: "flex",
  altText: `【${targetStaffName}】近7日班表預約查詢`,
  contents: {
    type: "bubble",
    size: "kilo",
    header: {
      type: "box",
      layout: "vertical",
      backgroundColor: "#0F2537",
      contents: [
        {
          type: "text",
          text: `📋 【${targetStaffName}】近 7 日班表`,
          weight: "bold",
          size: "md",
          color: "#FFFFFF"
        }
      ]
    },
    body: {
      type: "box",
      layout: "vertical",
      contents: contents
    }
  }
};

return [{
  json: {
    replyToken: replyToken,
    messages: [flexMessage]
  }
}];
